// Native lifecycle adaptation of published @mui/internal-docs-infra0.12.1-canary.42 useSearch.mjs; MIT2019 Material-UI SAS.
// Published JavaScript pure schema/flattening/ranking/URL bodies are retained; React state/effect wrappers become one initialized service.
import { create, insertMultiple, search as oramaSearch } from '@orama/orama';
import { pluginQPS } from '@orama/plugin-qps';
import { stemmer, language } from '@orama/stemmers/english';
import { stopwords as englishStopwords } from '@orama/stopwords/english';
import type { Result } from '@orama/orama';
import type {
  GenerateSlug,
  GroupedResults,
  PageSearchResult,
  SearchBy,
  SearchEngineOptions,
  SearchIndex,
  SearchResult,
  SitemapPage,
  SitemapSection,
  SitemapSectionData,
} from './types.js';
// https://github.com/oramasearch/orama/blob/main/packages/stopwords/lib/en.js
// Removed words that might be meaningful in a software documentation context
const stopWords = englishStopwords.filter(
  (word) =>
    word !== 'about' &&
    word !== 'but' &&
    // start of button
    word !== 'for' &&
    // part of form
    word !== 'between' &&
    word !== 'before' &&
    word !== 'after' &&
    word !== 'above' &&
    word !== 'below' &&
    word !== 'once' &&
    word !== 'then' &&
    word !== 'where' &&
    word !== 'to' &&
    word !== 'from' &&
    word !== 'up' &&
    word !== 'down' &&
    word !== 'in' &&
    word !== 'out' &&
    word !== 'on' &&
    word !== 'off' &&
    word !== 'over' &&
    word !== 'under',
);

/**
 * Type for our search document structure
 */

/**
 * Orama schema definition for our search document
 */
const searchSchema = {
  type: 'string',
  group: 'string',
  title: 'string',
  description: 'string',
  slug: 'string',
  sectionTitle: 'string',
  prefix: 'string',
  path: 'string',
  keywords: 'string',
  page: 'string',
  pageKeywords: 'string',
  sections: 'string',
  subsections: 'string',
  part: 'string',
  export: 'string',
  types: 'string',
  props: 'string',
  dataAttributes: 'string',
  cssVariables: 'string',
  section: 'string',
  subsection: 'string',
} as const;
export type SearchSchema = typeof searchSchema;

/**
 * Type for Orama search hit results
 */

/**
 * Default function to flatten a sitemap page into search results
 */
function defaultFlattenPage(
  page: SitemapPage,
  sectionData: SitemapSectionData,
  includeCategoryInGroup: boolean,
  excludeSections?: boolean,
  generateSlug?: GenerateSlug,
): SearchResult[] {
  const results: SearchResult[] = [];

  // Extract top-level sections and all subsections with their slugs
  // Re-slugify from titles using the provided slugify function to match actual page IDs
  const sections: { title: string; slug: string }[] = [];
  const subsections: {
    title: string;
    slug: string;
    parentSlugs: string[];
    parentTitles: string[];
  }[] = [];
  if (page.sections) {
    // Top-level sections are the direct children
    for (const [originalSlug, sectionInfo] of Object.entries(page.sections)) {
      // Use generateSlug if provided, otherwise use the original slug from sitemap
      const slug = generateSlug ? generateSlug(sectionInfo.title, []) : originalSlug;
      sections.push({
        title: sectionInfo.title,
        slug,
      });

      // Subsections are all nested children (recursively)
      if (sectionInfo.children && Object.keys(sectionInfo.children).length > 0) {
        const extractWithSlugs = (
          hierarchy: Record<string, SitemapSection>,
          parentSlugs: string[],
          parentTitles: string[],
        ): typeof subsections => {
          const items: typeof subsections = [];
          for (const [childOriginalSlug, childData] of Object.entries(hierarchy)) {
            // Use generateSlug if provided, otherwise use the original slug from sitemap
            // When generateSlug is provided, pass parent titles for context
            // (e.g., for Releases pages: v1.0.0-rc.0-autocomplete)
            const childSlug = generateSlug
              ? generateSlug(childData.title, parentTitles)
              : childOriginalSlug;
            const currentSlugs = [...parentSlugs, childSlug];
            const currentTitles = [...parentTitles, childData.title];
            items.push({
              title: childData.title,
              slug: childSlug,
              parentSlugs: currentSlugs,
              parentTitles: currentTitles,
            });
            if (childData.children && Object.keys(childData.children).length > 0) {
              items.push(...extractWithSlugs(childData.children, currentSlugs, currentTitles));
            }
          }
          return items;
        };
        subsections.push(...extractWithSlugs(sectionInfo.children, [slug], [sectionInfo.title]));
      }
    }
  }
  const flattened: Pick<PageSearchResult, 'keywords' | 'types' | 'sections' | 'subsections'> = {};
  if (page.keywords?.length) {
    flattened.keywords = page.keywords.join(' ');
  }
  if (page.types && page.types.length > 0) {
    flattened.types = page.types.join(' ');
  }
  if (sections.length > 0) {
    flattened.sections = sections.map((s) => s.title).join(' ');
  }
  if (subsections.length > 0) {
    flattened.subsections = subsections.map((s) => s.title).join(' ');
  }

  // Add base page result
  results.push({
    type: 'page',
    group: includeCategoryInGroup ? `${sectionData.title} Pages` : 'Pages',
    page: page.title,
    title: page.title,
    slug: page.slug,
    path: page.path,
    description: page.description,
    sectionTitle: sectionData.title,
    prefix: sectionData.prefix,
    ...(flattened.keywords
      ? {
          keywords: flattened.keywords,
        }
      : {}),
    ...(flattened.types
      ? {
          types: flattened.types,
        }
      : {}),
    ...(excludeSections
      ? {}
      : {
          sections: flattened.sections,
          subsections: flattened.subsections,
        }),
  });

  // Add entries for each part
  if (page.parts && Object.keys(page.parts).length > 0) {
    for (const [partName, partData] of Object.entries(page.parts)) {
      results.push({
        type: 'part',
        group: 'API Reference',
        part: partName,
        export: `${page.slug}.${partName}`,
        slug: partName.toLowerCase(),
        path: page.path,
        title: page.title ? `${page.title} ‣ ${partName}` : partName,
        description: page.description,
        sectionTitle: sectionData.title,
        prefix: sectionData.prefix,
        props: partData.props ? partData.props.join(' ') : '',
        dataAttributes: partData.dataAttributes ? partData.dataAttributes.join(' ') : '',
        cssVariables: partData.cssVariables ? partData.cssVariables.join(' ') : '',
        keywords: flattened.keywords,
      });
    }
  }

  // Add entries for each export
  if (page.exports && Object.keys(page.exports).length > 0) {
    for (const [exportName, exportData] of Object.entries(page.exports)) {
      // If export name matches page slug (case-insensitive), use #api-reference
      const exportSlug =
        exportName.toLowerCase() === page.slug.toLowerCase()
          ? 'api-reference'
          : exportName.toLowerCase();
      results.push({
        type: 'export',
        group: 'API Reference',
        export: exportSlug,
        slug: page.slug,
        path: page.path,
        title: exportName,
        description: page.description,
        sectionTitle: sectionData.title,
        prefix: sectionData.prefix,
        props: exportData.props ? exportData.props.join(' ') : '',
        dataAttributes: exportData.dataAttributes ? exportData.dataAttributes.join(' ') : '',
        cssVariables: exportData.cssVariables ? exportData.cssVariables.join(' ') : '',
        keywords: flattened.keywords,
      });
    }
  }

  // Add entries for each section
  for (const sectionItem of sections) {
    results.push({
      type: 'section',
      group: 'Sections',
      section: sectionItem.title,
      slug: `${page.slug}#${sectionItem.slug}`,
      path: page.path,
      title: page.title ? `${page.title} ‣ ${sectionItem.title}` : sectionItem.title,
      description: page.description,
      sectionTitle: sectionData.title,
      prefix: sectionData.prefix,
      keywords: flattened.keywords,
    });
  }

  // Add entries for each subsection
  for (const subsectionItem of subsections) {
    const fullTitle = subsectionItem.parentTitles.join(' ‣ ');
    results.push({
      type: 'subsection',
      group: 'Sections',
      subsection: fullTitle,
      slug: `${page.slug}#${subsectionItem.slug.toLowerCase()}`,
      path: page.path,
      title: page.title ? `${page.title} ‣ ${fullTitle}` : fullTitle,
      description: page.description,
      sectionTitle: sectionData.title,
      prefix: sectionData.prefix,
      keywords: flattened.keywords,
    });
  }
  return results;
}

/**
 * Default function to format search results
 */
function defaultFormatResult(hit: Result<SearchResult>): SearchResult {
  const base = {
    id: hit.id,
    title: hit.document.title,
    description: hit.document.description,
    slug: hit.document.slug,
    sectionTitle: hit.document.sectionTitle,
    prefix: hit.document.prefix,
    path: hit.document.path,
    score: hit.score,
    keywords: hit.document.keywords,
  };
  const type = hit.document.type;
  if (type === 'part') {
    return {
      ...base,
      type: 'part',
      part: hit.document.part,
      export: hit.document.export,
      props: hit.document.props,
      dataAttributes: hit.document.dataAttributes,
      cssVariables: hit.document.cssVariables,
    };
  }
  if (type === 'export') {
    return {
      ...base,
      type: 'export',
      export: hit.document.export,
      props: hit.document.props,
      dataAttributes: hit.document.dataAttributes,
      cssVariables: hit.document.cssVariables,
    };
  }
  if (type === 'section') {
    return {
      ...base,
      type: 'section',
      section: hit.document.section,
    };
  }
  if (type === 'subsection') {
    return {
      ...base,
      type: 'subsection',
      subsection: hit.document.subsection,
    };
  }

  // Default to page type
  return {
    ...base,
    type: 'page',
    page: hit.document.title,
    ...(hit.document.sections
      ? {
          sections: hit.document.sections,
        }
      : {}),
    ...(hit.document.subsections
      ? {
          subsections: hit.document.subsections,
        }
      : {}),
  };
}
export const defaultSearchBoost = {
  type: 100,
  group: 100,
  slug: 2,
  path: 2,
  title: 2,
  page: 10,
  pageKeywords: 15,
  description: 1.5,
  part: 1.5,
  export: 1.3,
  types: 2,
  sectionTitle: 50,
  section: 3,
  subsection: 2.5,
  props: 1.5,
  dataAttributes: 1.5,
  cssVariables: 1.5,
  sections: 0.7,
  subsections: 0.3,
  keywords: 1.5,
};

/**
 * Hook for managing search functionality with Orama
 *
 * @param options Configuration options for search behavior
 * @returns Search state and functions
 */
export function createSearchEngine(options: SearchEngineOptions) {
  const {
    sitemap: sitemapImport,
    maxDefaultResults,
    tolerance = 1,
    limit: defaultLimit = 20,
    boost = defaultSearchBoost,
    enableStemming = true,
    generateSlug,
    flattenPage = defaultFlattenPage,
    formatResult = defaultFormatResult,
    showPrivatePages = false,
  } = options;
  let index: SearchIndex | null = null;
  let defaultResults: GroupedResults = {
    results: [],
    count: 0,
    elapsed: { raw: 0, formatted: '0ms' },
  };
  let results = defaultResults;
  const setIndex = (value: SearchIndex) => {
    index = value;
  };
  const setDefaultResults = (value: GroupedResults) => {
    defaultResults = value;
  };
  const setResults = (value: GroupedResults) => {
    results = value;
  };
  const ready = (async () => {
    const { sitemap } = await sitemapImport();
    if (!sitemap) {
      console.error('Sitemap is undefined');
      return;
    }
    const searchIndex = await create({
      schema: searchSchema,
      components: enableStemming
        ? {
            tokenizer: {
              stemming: true,
              language,
              stemmer,
              stemmerSkipProperties: [
                'type',
                'group',
                'slug',
                'sectionTitle',
                'page',
                'part',
                'export',
                'dataAttributes',
                'cssVariables',
                'props',
              ],
              stopWords,
            },
          }
        : undefined,
      plugins: [pluginQPS()],
    });

    // Flatten the sitemap data structure to a single array of pages
    const pages: SearchResult[] = [];
    const pageResultsByGroup: Record<string, SearchResult[]> = {};
    let pageResultsCount = 0;
    Object.entries(sitemap.data).forEach(([_sectionKey, sectionData]) => {
      (sectionData.pages || []).forEach((page) => {
        // Skip private pages in public deployments
        if (!showPrivatePages && page.audience === 'private') {
          return;
        }
        const flattened = flattenPage(
          page,
          sectionData,
          options.includeCategoryInGroup || false,
          options.excludeSections,
          generateSlug,
        );
        pages.push(...flattened);

        // Add the first result (page type) to default results, grouped by their group
        if (
          (maxDefaultResults === undefined || pageResultsCount < maxDefaultResults) &&
          flattened.length > 0
        ) {
          const pageResult = flattened[0];
          const group = pageResult.group || 'Pages';
          if (!pageResultsByGroup[group]) {
            pageResultsByGroup[group] = [];
          }
          pageResultsByGroup[group].push(pageResult);
          pageResultsCount += 1;
        }
      });
    });

    // Insert a dummy document with all fields to ensure QPS plugin initializes stats for all properties.
    // This is needed because QPS only creates stats for properties that have data inserted.
    // Using empty strings ensures no false matches while still initializing the stats.
    const dummyDoc = {
      type: '',
      group: '',
      title: '',
      description: '',
      slug: '',
      sectionTitle: '',
      prefix: '',
      path: '',
      keywords: '',
      page: '',
      pageKeywords: '',
      sections: '',
      subsections: '',
      part: '',
      export: '',
      props: '',
      dataAttributes: '',
      cssVariables: '',
      section: '',
      subsection: '',
    };
    await insertMultiple(searchIndex, [dummyDoc, ...pages]);
    const pageResultsGrouped = Object.entries(pageResultsByGroup).map(([group, items]) => ({
      group,
      items,
    }));
    const defaultResultsValue = {
      results: pageResultsGrouped,
      count: pageResultsCount,
      elapsed: {
        raw: 0,
        formatted: '0ms',
      },
    };
    setIndex(searchIndex);
    setDefaultResults(defaultResultsValue);
    setResults(defaultResultsValue);
  })();
  const search = async (
    value: string,
    { facets, groupBy, limit = defaultLimit, where }: SearchBy = {},
  ): Promise<void> => {
    if (!index || !value.trim()) {
      setResults(defaultResults);
      return;
    }
    const valueLower = value.toLowerCase();
    // Normalize for comparison: convert spaces/hyphens to a common format
    const valueNormalized = valueLower.replace(/[-\s]+/g, ' ').trim();

    // For longer search terms, skip custom sorting and rely on Orama's scoring
    // The overhead of checking exact/startsWith/contains isn't worth it
    const useCustomSort = valueLower.length <= 20;

    // Cache for computed document properties to avoid repeated string operations
    const cache = new Map<
      string,
      { titleLower: string; slugLower: string; slugNormalized: string }
    >();
    const getDocProps = (doc: SearchResult) => {
      const key = doc.slug; // Use slug as cache key since it's unique per document
      let props = cache.get(key);
      if (!props) {
        const titleLower = doc.title.toLowerCase();
        const slugLower = doc.slug.toLowerCase();
        props = {
          titleLower,
          slugLower,
          slugNormalized: slugLower.replace(/-/g, ' '),
        };
        cache.set(key, props);
      }
      return props;
    };
    const searchResults = await oramaSearch<SearchIndex, SearchResult>(index, {
      term: value,
      facets,
      groupBy,
      where,
      limit,
      tolerance,
      boost,
      sortBy: useCustomSort
        ? ([_, aScore, aDocument], [__, bScore, bDocument]) => {
            const a = getDocProps(aDocument);
            const b = getDocProps(bDocument);

            // Prioritize exact matches (short-circuit on first match)
            const aExact =
              a.titleLower === valueLower ||
              a.slugLower === valueLower ||
              a.slugNormalized === valueNormalized;
            const bExact =
              b.titleLower === valueLower ||
              b.slugLower === valueLower ||
              b.slugNormalized === valueNormalized;
            if (aExact !== bExact) {
              return aExact ? -1 : 1;
            }

            // Then prioritize startsWith matches
            const aStartsWith =
              a.titleLower.startsWith(valueLower) || a.slugNormalized.startsWith(valueNormalized);
            const bStartsWith =
              b.titleLower.startsWith(valueLower) || b.slugNormalized.startsWith(valueNormalized);
            if (aStartsWith !== bStartsWith) {
              return aStartsWith ? -1 : 1;
            }

            // Then prioritize contains matches
            const aContains =
              a.titleLower.includes(valueLower) || a.slugNormalized.includes(valueNormalized);
            const bContains =
              b.titleLower.includes(valueLower) || b.slugNormalized.includes(valueNormalized);
            if (aContains !== bContains) {
              return aContains ? -1 : 1;
            }

            // Then sort by score descending
            return bScore - aScore;
          }
        : undefined,
    });
    const count = searchResults.count;
    const elapsed = searchResults.elapsed;
    if (searchResults.groups) {
      const groupedResults = searchResults.groups.map((group) => ({
        group: group.values.join(' '),
        items: group.result.map(formatResult),
      }));
      setResults({
        results: groupedResults,
        count,
        elapsed,
      });
      return;
    }
    const formattedResults = searchResults.hits.map(formatResult);
    setResults({
      results: [
        {
          group: 'Default',
          items: formattedResults,
        },
      ],
      count,
      elapsed,
    });
  };

  /**
   * Build a URL from a search result
   * Handles path normalization and hash fragments for different result types
   */
  const buildResultUrl = (result: SearchResult): string => {
    let url = result.path.startsWith('./')
      ? `${result.prefix}${result.path.replace(/^\.\//, '').replace(/\/page\.mdx$/, '')}`
      : result.path;

    // Add hash for non-page types
    if ('type' in result && result.type !== 'page') {
      let hash;
      if (result.type === 'section' || result.type === 'subsection') {
        // For sections and subsections, extract hash from the slug field
        // which already contains the page slug + hash (e.g., "button#api-reference")
        const hashIndex = result.slug.indexOf('#');
        hash = hashIndex !== -1 ? result.slug.substring(hashIndex + 1) : '';
      } else if (result.type === 'part') {
        hash = result.part.toLowerCase();
      } else if (result.type === 'export') {
        hash = result.export; // already lowercase or api-reference
      } else {
        hash = '';
      }
      if (hash) {
        url += `#${hash}`;
      }
    }
    return url;
  };
  return {
    ready,
    get results() {
      return results;
    },
    get isReady() {
      return index !== null;
    },
    search,
    get defaultResults() {
      return defaultResults;
    },
    buildResultUrl,
  };
}

import { registerHooks } from 'node:module';
import { test } from 'node:test';
import assert from 'node:assert/strict';
// Native Node strip-types resolves the canonical TS metadata behind the Vite
// .js import spelling; the actual Source search/index/ranking bodies still run.
registerHooks({
  resolve(specifier, context, nextResolve) {
    if (specifier.endsWith('/fixtures/src/lib/docs/content.js'))
      return nextResolve(specifier.slice(0, -3) + '.ts', context);
    if (
      specifier.startsWith('.') &&
      specifier.endsWith('.js') &&
      context.parentURL?.startsWith(new URL('../src/lib/docs/', import.meta.url).href)
    )
      return nextResolve(specifier.slice(0, -3) + '.ts', context);
    return nextResolve(specifier, context);
  },
});
const { createSearchEngine } = await import('../src/lib/docs/search/engine.ts');
test('actual native declaration metadata supports nonempty Source QPS queries', async () => {
  const engine = createSearchEngine({
    sitemap: () => import('../src/lib/docs/search/sitemap.ts'),
    tolerance: 0,
    includeCategoryInGroup: true,
    excludeSections: true,
  });
  await engine.ready;
  for (const [term, path] of [
    ['button', '/docs/components/button/'],
    ['avatar', '/docs/components/avatar/'],
    ['remote form', '/docs/components/remote-form/'],
  ]) {
    await engine.search(term, {
      groupBy: { properties: ['group'], maxResult: 5 },
    });
    const results = engine.results.results.flatMap((group) => group.items);
    assert.ok(results.length > 0);
    assert.equal(engine.buildResultUrl(results[0]), path);
  }
});

// Evidence tooling: compare the maintained typed helpers with the frozen
// JavaScript checkpoint using this workspace's actual pinned TypeScript compiler.
// This runs no alternate parser/search implementation and needs no network.
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '../../..');
const require = createRequire(resolve(root, 'apps/docs/package.json'));
const ts = require('typescript');
const baseline = 'fd4928c034be417fcdc0451f4214c34ddbc09510';
const highlight = 'apps/docs/src/lib/docs/highlight';
const historical = JSON.parse(
  readFileSync(resolve(root, 'docs/receipts/docs/parser-source-files.json'), 'utf8'),
);
const targets = [
  ...historical.map((entry) => ({
    ...entry,
    source: entry.target,
    target: entry.target.replace(/\.mjs$/, '.ts'),
  })),
  {
    source: 'apps/docs/src/lib/docs/search/engine.js',
    target: 'apps/docs/src/lib/docs/search/engine.ts',
    original: 'useSearch/useSearch.mjs',
    originalSha256: '342a13b974150122216ed5c85ccdfe86bdc7bda5eaf10774473886eadf4dd84d',
  },
];

function sha256(source) {
  return createHash('sha256').update(source).digest('hex');
}
function runtime(source, fileName) {
  const erased = ts.transpileModule(source, {
    fileName,
    compilerOptions: {
      target: ts.ScriptTarget.ESNext,
      module: ts.ModuleKind.ESNext,
      removeComments: true,
    },
  }).outputText;
  const ast = ts.createSourceFile(
    'runtime.js',
    erased,
    ts.ScriptTarget.Latest,
    true,
    ts.ScriptKind.JS,
  );
  // Type assertions can leave parentheses, and a typed shorthand property may
  // spell `children: children`. Normalize only those equivalent AST forms.
  const transformed = ts.transform(ast, [
    (context) => {
      function visit(node) {
        if (
          ts.isStringLiteral(node) &&
          (ts.isImportDeclaration(node.parent) ||
            ts.isExportDeclaration(node.parent) ||
            (ts.isCallExpression(node.parent) &&
              node.parent.expression.kind === ts.SyntaxKind.ImportKeyword))
        )
          return ts.factory.createStringLiteral(node.text.replace(/\.mjs$/, '.js'));
        if (ts.isParenthesizedExpression(node)) return ts.visitNode(node.expression, visit);
        if (ts.isShorthandPropertyAssignment(node) && !node.objectAssignmentInitializer)
          return ts.factory.createPropertyAssignment(node.name, node.name);
        return ts.visitEachChild(node, visit, context);
      }
      return (node) => ts.visitNode(node, visit);
    },
  ]);
  function shape(node) {
    const children = [];
    ts.forEachChild(node, (child) => {
      children.push(shape(child));
    });
    return {
      kind: ts.SyntaxKind[node.kind],
      ...(ts.isIdentifier(node) || ts.isLiteralExpression(node) || ts.isTemplateLiteralToken(node)
        ? { text: node.text }
        : {}),
      ...(ts.isTemplateLiteralToken(node) ? { rawText: node.rawText ?? node.getText(ast) } : {}),
      ...(ts.isVariableDeclarationList(node)
        ? { declaration: node.flags & (ts.NodeFlags.Let | ts.NodeFlags.Const) }
        : {}),
      ...(ts.isPrefixUnaryExpression(node) || ts.isPostfixUnaryExpression(node)
        ? { operator: ts.SyntaxKind[node.operator] }
        : {}),
      children,
    };
  }
  const printed = JSON.stringify(shape(transformed.transformed[0]));
  transformed.dispose();
